// ════════════════════════════════════════════════════════════════════
//  หน้าตาคลิป — ๓ แบบให้เจ้าของเลือกจากของจริง
//
//  ★★ ทำไมต้องทำหลายแบบให้ดู แทนที่จะเลือกให้เอง ★★
//    หน้าตาเป็นเรื่องรสนิยมและการใช้งานจริงของครู ซึ่งเจ้าของรู้ดีกว่า
//    เดาแล้ว build ทีละรอบเสียเวลาทั้งสองฝ่าย — ทำของจริงให้ดูแล้วชี้ทีเดียวจบ
//
//  ★ คลิปแนวตั้งถูกดูบนมือถือ · "ตัวโน้ตอ่านออกไหม" สำคัญกว่า "เห็นทั้งเพลงไหม"
//    แบบ ข กับ ค จึงซูมเข้าไปที่บรรทัดที่กำลังเล่น
// ════════════════════════════════════════════════════════════════════
export type Rect = { x: number; y: number; w: number; h: number };

export type Sheet = {
  img: CanvasImageSource;
  w: number; h: number;
  /** บรรทัดบนกระดาษ พร้อมช่วงห้องที่มันครอบ */
  lines: Array<Rect & { from: number; to: number }>;
  hongs: Map<number, Rect>;
  cells: Map<string, Rect[]>;
};
/** หนึ่งบรรทัดสากล = หนึ่งภาพ พร้อมช่วงห้องที่มันครอบ */
export type WesternSystem = {
  img: CanvasImageSource; w: number; h: number;
  bars: Map<number, Rect>; from: number; to: number;
};
export type Western = { systems: WesternSystem[] };

const CELL_INK = 'rgba(226,59,46,.16)';
const HONG_INK = 'rgba(226,59,46,.07)';
const BAR_INK = 'rgba(226,59,46,.14)';
const PAPER = '#fffdf7';
const INK = '#2a2118';
const MUTED = '#6f6151';

/** อ่านตำแหน่งทุกอย่างจาก DOM จริงครั้งเดียว — ★ ห้ามอ่านระหว่างอัด (ช้าและอาจขยับ) */
export function readSheet(paper: HTMLElement): Omit<Sheet, 'img' | 'w' | 'h'> {
  const base = paper.getBoundingClientRect();
  const rel = (el: Element): Rect => {
    const b = el.getBoundingClientRect();
    return { x: b.left - base.left, y: b.top - base.top, w: b.width, h: b.height };
  };
  const hongs = new Map<number, Rect>();
  const cells = new Map<string, Rect[]>();
  const lines: Array<Rect & { from: number; to: number }> = [];
  paper.querySelectorAll('.tn-line').forEach((ln) => {
    const nos: number[] = [];
    ln.querySelectorAll('.tn-hong[data-hong]').forEach((h) => {
      const no = Number((h as HTMLElement).dataset.hong);
      if (!Number.isFinite(no)) return;
      nos.push(no);
      hongs.set(no, rel(h));
      h.querySelectorAll('.tn-cell[data-t]').forEach((c) => {
        const key = `${no}.${Number((c as HTMLElement).dataset.t)}`;
        cells.set(key, (cells.get(key) || []).concat(rel(c)));
      });
    });
    if (nos.length) lines.push({ ...rel(ln), from: Math.min(...nos), to: Math.max(...nos) });
  });
  return { lines, hongs, cells };
}

/** ★★ แผ่นสากล: **หนึ่งบรรทัด = หนึ่ง `<svg>` ของตัวเอง** ★★
 *  ไม่ใช่กลุ่มใน svg เดียว (ดู WesternSheet.tsx ที่วนสร้างทีละบรรทัด)
 *  ตอนแรกไปหา `.wn-system` ข้างใน svg เลยได้ 0 บรรทัดแล้วแบบ ค ออกมาโล่ง
 *  → รับ svg **ทีละใบ** แล้วนับใบนั้นเป็นหนึ่งบรรทัด */
export function readWesternSystem(svg: SVGElement): {
  bars: Map<number, Rect>; from: number; to: number;
} {
  const base = svg.getBoundingClientRect();
  const bars = new Map<number, Rect>();
  const nos: number[] = [];
  svg.querySelectorAll('.wn-hl[data-hong]').forEach((b) => {
    const no = Number((b as SVGElement).dataset.hong);
    if (!Number.isFinite(no)) return;
    nos.push(no);
    const r = b.getBoundingClientRect();
    bars.set(no, { x: r.left - base.left, y: r.top - base.top, w: r.width, h: r.height });
  });
  return { bars, from: nos.length ? Math.min(...nos) : 0, to: nos.length ? Math.max(...nos) : 0 };
}

export type FrameCtx = {
  ctx: CanvasRenderingContext2D; W: number; H: number;
  sheet: Sheet; western?: Western;
  title: string; subtitle: string;
  hongNo: number; slotTick: number;
  /** ภาพชิ้นที่เตรียมไว้แล้ว (คีย์จาก `planFor`) — ★ ต้องเตรียมก่อนวาดเสมอ */
  tiles?: Map<string, CanvasImageSource>;
};

/** ชิ้นภาพหนึ่งชิ้นที่เฟรมนี้ต้องใช้
 *  ★★ `crop` เป็นหน่วยของต้นฉบับ · `dst` เป็นพิกเซลบนคลิป — ตัว rasterize
 *    จะสร้างภาพ **เท่า dst พอดี** จึงวาดแบบ 1:1 ไม่ต้องขยาย = คมที่สุดเท่าที่ทำได้ */
export type Tile = {
  key: string;
  /** 'thai' = ตัดจากกระดาษไทย · 'west' = บรรทัดสากลใบที่ `sys` */
  kind: 'thai' | 'west';
  sys?: number;
  crop: Rect;
  dst: Rect;
};

const bg = (c: FrameCtx) => { c.ctx.fillStyle = PAPER; c.ctx.fillRect(0, 0, c.W, c.H); };

/** ★★ ขนาดทุกอย่างคิดจาก **ด้านสั้นของกรอบ** ไม่ใช่ค่าตายตัว ★★
 *  เจ้าของสั่งเพิ่มแนวนอน (2026-08-19) — ถ้าผูกกับความกว้าง ส่วนหัวจะโตขึ้น
 *  เกือบเท่าตัวตอนสลับเป็น 1920×1080 · ถ้าผูกกับความสูงก็จะเล็กจนอ่านไม่ออก
 *  → ผูกกับด้านสั้น ได้ขนาดเท่ากันทั้งสองแนวโดยไม่ต้องมีตัวเลขสองชุด */
const unit = (c: FrameCtx) => Math.min(c.W, c.H) / 1080;
/** เนื้อกระดาษเริ่มตรงนี้เสมอ — ยึดบนเป็นหลัก ไม่จัดกึ่งกลางแนวตั้ง */
const headH = (c: FrameCtx) => Math.round(128 * unit(c));
/** ★ ที่ว่างล่างเหลือไว้ให้แถบเครดิตอย่างเดียว (ป้ายบอกตำแหน่งถูกตัดออกแล้ว)
 *  ลดจาก 90 เหลือ 64 = โน้ตได้ที่เพิ่มขึ้นเกือบสองบรรทัดในแนวตั้ง */
const botPad = (c: FrameCtx) => Math.round(64 * unit(c));
const side = (c: FrameCtx) => Math.round(16 * unit(c));

/** แถบหัวคลิป — ชื่อเพลงกับอัตราจังหวะ · ★ ห้ามใส่ชื่อโปรแกรม/โลโก้/เว็บ
 *  (กฎเดียวกับกระดาษที่พิมพ์: ของที่ออกไปเป็นของลูกค้า)
 *  ★★ กึ่งกลางด้วยการ **วัดความกว้างจริง** ไม่พึ่ง `textAlign` ★★
 *    ฟอนต์ไทยบางตัวมีระยะข้างซ้าย/ขวาไม่เท่ากัน ทำให้ตาเห็นว่าเยื้อง
 *    ทั้งที่ `textAlign='center'` ถูกแล้ว — วัดเองแล้ววางเองจึงตรงกลางจริง
 *  ★ ขนาดลดจาก 46/26 เหลือ 34/20 (เจ้าของทัก 2026-08-19: "ใหญ่ไปไม่สมสัดส่วน") */
function header(c: FrameCtx) {
  const u = unit(c);
  const put = (text: string, font: string, color: string, y: number) => {
    if (!text) return;
    c.ctx.font = font;
    c.ctx.fillStyle = color;
    c.ctx.textAlign = 'left';
    const w = c.ctx.measureText(text).width;
    c.ctx.fillText(text, Math.round((c.W - w) / 2), y);
  };
  put(c.title, `700 ${Math.round(34 * u)}px Anuphan, sans-serif`, INK, Math.round(58 * u));
  put(c.subtitle, `${Math.round(20 * u)}px 'IBM Plex Sans Thai', sans-serif`, MUTED, Math.round(90 * u));
}

/** วาดไฮไลต์ห้อง/ช่อง โดยแปลงพิกัดกระดาษ → พิกัดภาพ */
function marks(c: FrameCtx, sx: number, sy: number, k: number) {
  const hr = c.sheet.hongs.get(c.hongNo);
  if (hr) {
    c.ctx.fillStyle = HONG_INK;
    c.ctx.fillRect(sx + hr.x * k, sy + hr.y * k, hr.w * k, hr.h * k);
  }
  for (const cr of c.sheet.cells.get(`${c.hongNo}.${c.slotTick}`) || []) {
    c.ctx.fillStyle = CELL_INK;
    c.ctx.fillRect(sx + cr.x * k, sy + cr.y * k, cr.w * k, cr.h * k);
  }
}

// ════════════════════════════════════════════════════════════════════
//  ★★ กติกาที่เจ้าของเคาะ 2026-08-19 ★★
//   ๑ **หนึ่งคลิป = ระบบเดียว** ไทย *หรือ* สากล — ไม่ทำคู่กันในคลิปเดียว
//   ๒ **ยึดตำแหน่งด้านบนเป็นหลัก** ไม่จัดกึ่งกลางแนวตั้ง
//   ๓ ส่วนหัวเล็กลงและชื่อเพลงต้องอยู่กึ่งกลางจริง
//   ๔ เพลงยาว **ต้องเลื่อนหน้าให้อัตโนมัติ** ตามหัวเข็ม
// ════════════════════════════════════════════════════════════════════


/** ★★ วาดเฉพาะ "ส่วนของกระดาษที่ใช้จริง" ★★
 *  ของเดิมวาดกระดาษทั้งแผ่นแล้วค่อยตัดด้วยกรอบ — เพลงสาธุการมี 54 บรรทัด
 *  ทุกเฟรมจึงวาดภาพสูงกว่าจอ 5 เท่าทิ้งไปเปล่า ๆ (คลิป 20 วิ ใช้เวลา 112 วิ)
 *  drawImage แบบ 9 ตัวแปรบอก "เอาช่วงไหนของต้นฉบับ" ได้ตรง ๆ → เร็วขึ้นมาก
 *  @param src ช่วงบนกระดาษ (หน่วยเดียวกับ rect ที่อ่านจาก DOM)
 *  @param k   อัตราขยายจากหน่วยกระดาษ → พิกเซลของคลิป */
/** วาดชิ้นภาพที่เตรียมไว้ลงตำแหน่งของมัน — ★ 1:1 ไม่มีการขยาย */
function blit(c: FrameCtx, t: Tile) {
  if (COLLECT) { COLLECT.push(t); return; }
  const img = c.tiles?.get(t.key);
  if (!img) return;
  c.ctx.drawImage(img, t.dst.x, t.dst.y, t.dst.w, t.dst.h);
}

/** ★★ เลื่อนหน้าอัตโนมัติ ★★ เพลงจริงยาวหลายสิบบรรทัด วางทั้งเพลงค้างไว้
 *  = ตัวโน้ตเล็กจนอ่านไม่ออก · ที่นี่จึงแบ่งเป็น "หน้า" ตามจำนวนบรรทัดที่ใส่ได้จริง
 *  แล้ว **กระโดดทีละหน้า** เมื่อหัวเข็มข้ามไปบรรทัดที่ไม่ได้อยู่ในหน้านั้น
 *  ★ กระโดดทีละหน้า ไม่ใช่ไถทีละพิกเซล — คนอ่านโน้ตต้องการภาพนิ่งให้สายตาเกาะ
 *    ไถตลอดเวลาทำให้อ่านยากกว่าเดิม (และเปลืองเฟรมที่ต้องวาดใหม่)
 *  @returns ดัชนีบรรทัดแรกของหน้าที่ต้องแสดง กับจำนวนบรรทัดต่อหน้า
 */
/** ★ เพดานบรรทัดต่อหน้า — ตั้งสูงไว้โดยตั้งใจ ให้ **ความสูงของจอเป็นตัวตัดสิน**
 *  ลองตั้ง 6 แล้วเห็นจากคลิปจริงว่าเหลือที่ว่างสองในสามจอ (2026-08-19)
 *  ★ "เต็มหน้า" กับ "ซูม" เป็นคนละของกัน — อยากได้ตัวโน้ตใหญ่ให้ใช้แบบซูม
 *    ไม่ใช่มาลดบรรทัดของแบบเต็มหน้าแล้วได้ทั้งเล็กทั้งโล่ง */
const MAX_LINES = 99;

function pageOf(lineIdx: number, heights: number[], avail: number) {
  // ไล่ประกอบหน้าตั้งแต่บรรทัดแรก — จำนวนบรรทัดต่อหน้าไม่เท่ากันได้
  // (บรรทัดที่มีป้ายกำกับห้อง/เนื้อร้องสูงกว่าบรรทัดธรรมดา)
  let start = 0;
  while (start < heights.length) {
    let used = 0; let end = start;
    while (end < heights.length && used + heights[end] <= avail && end - start < MAX_LINES) {
      used += heights[end]; end += 1;
    }
    if (end === start) end = start + 1;                 // บรรทัดเดียวก็ยังไม่พอ = ยัดไปหนึ่งบรรทัด
    if (lineIdx < end) return { start, end };
    start = end;
  }
  return { start: Math.max(0, heights.length - 1), end: heights.length };
}

// ── ไทย · เต็มหน้า (เลื่อนหน้าอัตโนมัติ) ──────────────────────────────
export function drawThaiPage(c: FrameCtx) {
  bg(c); header(c);
  const SIDE = side(c); const HEAD_H = headH(c);
  const k = (c.W - SIDE * 2) / c.sheet.w;
  const idx = Math.max(0, c.sheet.lines.findIndex((l) => c.hongNo >= l.from && c.hongNo <= l.to));
  // ★★ ความสูงของหน้าต้องวัดจาก **ขอบจริง** (บนของบรรทัดแรก → ล่างของบรรทัดสุดท้าย)
  //   ไม่ใช่ผลบวกความสูงรายบรรทัด — ระหว่างบรรทัดมีระยะห่างที่ไม่ได้อยู่ในความสูง
  //   ของใคร ผลบวกจึงไม่ตรงกับที่ตาเห็น แล้วแถบเลขห้องของบรรทัดถัดไปโผล่ที่ขอบล่าง
  //   (เห็นจากคลิปแนวนอนจริง 2026-08-19 · แก้รอบแรกด้วยการหั่นระยะเผื่อแล้วยังโผล่)
  const L = c.sheet.lines;
  const span = (a2: number, b2: number) => (L[b2].y + L[b2].h) - L[a2].y;
  const hs = L.map((_, i) => (i === 0 ? span(0, 0) : span(i - 1, i) - span(i - 1, i - 1)) * k);
  const { start, end } = pageOf(idx, hs, c.H - HEAD_H - botPad(c));

  // ★★ กรอบตัดต้องสูงเท่า **หน้านั้น** ไม่ใช่เท่าพื้นที่ว่างทั้งหมด ★★
  //   ตัดด้วยพื้นที่ว่าง = บรรทัดที่เหลือของเพลงไหลทะลุลงมาต่อ ทั้งที่ป้ายบอกว่า
  //   "บรรทัดที่ 7–12" (เจอจากคลิปตัวอย่างจริง 2026-08-19 — โค้ดไม่ฟ้องอะไรเลย)
  // ★★ ต้องเผื่อขอบบน ★★ ตัดที่ `L[start].y` พอดีเป๊ะ ทำให้ **เส้นกรอบบนของบรรทัดแรก
  //   หายไปทั้งเส้น** (เจ้าของจับได้จากคลิปจริง 2026-08-20 — เส้นหนา 1 px ตกขอบภาพ
  //   ตอนปัดเศษ) · เผื่อแค่ด้านบน **ห้ามเผื่อด้านล่าง** ไม่งั้นแถวเลขห้องของบรรทัด
  //   ถัดไปโผล่มาครึ่งแถว (บทเรียนเดิมจากคลิปแนวนอน 2026-08-19)
  const TOP_PAD = 4;
  const cropY = Math.max(0, L[start].y - TOP_PAD);
  const cropH = span(start, end - 1) + (L[start].y - cropY);
  const pageH = cropH * k;
  blit(c, {
    key: `thai-page:${start}:${end}:${Math.round(k * 1000)}`,
    kind: 'thai',
    crop: { x: 0, y: cropY, w: c.sheet.w, h: cropH },
    dst: { x: SIDE, y: HEAD_H, w: c.sheet.w * k, h: pageH },
  });
  const top = HEAD_H - cropY * k;
  c.ctx.save();
  c.ctx.beginPath();
  // ★ เผื่อขอบบนได้ แต่ **ขอบล่างห้ามเผื่อ** — เผื่อ 8 px แล้วแถบเลขห้องของ
  //   บรรทัดถัดไปโผล่มาครึ่งแถวที่ขอบล่าง (เห็นจากคลิปแนวนอนจริง 2026-08-19)
  c.ctx.rect(0, HEAD_H - 8, c.W, pageH + 8);
  c.ctx.clip();
  marks(c, SIDE, top, k);
  c.ctx.restore();
  foot(c);
}

// ── ไทย · ซูม (4 ห้องต่อแถว · ซ้อนแถวจนเต็มจอ) ──────────────────────
//  ★★ ทำไมไม่ใช่ "หน้าต่างเดียวกลางจอ" อย่างเดิม ★★ เปิดคลิปจริงดูแล้ว (2026-08-20)
//    โน้ต 4 ห้องเป็นแถบเตี้ย ๆ กว้างเต็มจอ — แนวตั้งจึงเหลือกระดาษเปล่าราว ๔ ใน ๕ จอ
//    → ซ้อนแถวลงไปจนเต็มความสูง แล้ว **เน้นแถวที่กำลังเล่น** ตัวโน้ตยังใหญ่เท่าเดิม
//      (ใหญ่กว่าแบบเต็มหน้าราวสองเท่า) แต่คนดูเห็นทางข้างหน้า–ข้างหลังด้วย
//    ★ แถวอื่นจางลง ไม่ใช่หายไป — คนหัดใหม่ตามได้ว่ากำลังจะไปไหนต่อ
const WINDOW_BARS = 4;
const ROW_GAP = 34;          // ระยะห่างระหว่างแถว (คูณ unit)
const DIM_ROW = 0.42;        // ความจางของแถวที่ไม่ได้เล่นอยู่

type Win = { from: number; to: number } & Rect;

/** หั่นทั้งเพลงเป็นหน้าต่างละ 4 ห้อง เรียงตามลำดับที่เล่นจริง
 *  ★ หั่น **ทีละบรรทัด** ไม่ใช่ทีละ 4 ห้องรวด — หน้าต่างต้องไม่คร่อมสองบรรทัด
 *    เพราะบรรทัดคือหน่วยที่ครูใช้อ่าน และภาพที่ตัดมาก็มาจากบรรทัดเดียวเท่านั้น */
function allWindows(c: FrameCtx): Win[] {
  const out: Win[] = [];
  for (const line of c.sheet.lines) {
    for (let from = line.from; from <= line.to; from += WINDOW_BARS) {
      const to = Math.min(line.to, from + WINDOW_BARS - 1);
      const a = c.sheet.hongs.get(from);
      const b = c.sheet.hongs.get(to);
      if (!a || !b) continue;
      out.push({ from, to, x: a.x, w: (b.x + b.w) - a.x, y: line.y, h: line.h });
    }
  }
  return out;
}

export function drawThaiZoom(c: FrameCtx) {
  bg(c); header(c);
  const wins = allWindows(c);
  if (!wins.length) return;
  const u = unit(c);
  const SIDE = side(c); const HEAD_H = headH(c);
  const cur = Math.max(0, wins.findIndex((w) => c.hongNo >= w.from && c.hongNo <= w.to));

  // ★ มาตราส่วนคิดจาก **หน้าต่างที่เต็ม 4 ห้อง** ตัวเดียวกันทั้งคลิป — ถ้าคิดจาก
  //   หน้าต่างที่กำลังเล่น แถวท้ายบรรทัดที่มี 1–3 ห้องจะทำให้ตัวโน้ตโตขึ้นวูบ
  const full = wins.find((w) => w.to - w.from + 1 === WINDOW_BARS) || wins[cur];
  const k = (c.W - SIDE * 2) / full.w;
  const gap = Math.round(ROW_GAP * u);
  const heights = wins.map((w) => w.h * k + gap);
  const { start, end } = pageOf(cur, heights, c.H - HEAD_H - botPad(c));

  let y = HEAD_H;
  for (let i = start; i < end; i += 1) {
    const w = wins[i];
    const dst = { x: SIDE, y, w: w.w * k, h: w.h * k };
    const active = i === cur;
    if (!active) c.ctx.globalAlpha = DIM_ROW;
    blit(c, {
      key: `thai-zoom:${w.from}:${w.to}:${Math.round(k * 1000)}`,
      kind: 'thai',
      // ★ เผื่อขอบบน 4 px เหมือนแบบเต็มหน้า — เส้นกรอบบนของแถวหายด้วยเหตุเดียวกัน
      crop: { x: w.x, y: Math.max(0, w.y - 4), w: w.w, h: w.h + Math.min(4, w.y) },
      dst,
    });
    c.ctx.globalAlpha = 1;
    if (active) {
      c.ctx.save();
      c.ctx.beginPath();
      c.ctx.rect(0, dst.y - 6, c.W, dst.h + 12);
      c.ctx.clip();
      marks(c, SIDE - w.x * k, dst.y - w.y * k, k);
      c.ctx.restore();
    }
    y += heights[i];
  }
  foot(c);
}

// ── สากล · เต็มหน้า (เลื่อนหน้าอัตโนมัติ) ─────────────────────────────
export function drawWesternPage(c: FrameCtx) {
  bg(c); header(c);
  const wn = c.western;
  if (!wn || !wn.systems.length) return;
  const SIDE = side(c); const HEAD_H = headH(c);
  const GAPY = Math.round(24 * unit(c));
  const k = (c.W - SIDE * 2) / wn.systems[0].w;
  const hs = wn.systems.map((sy) => sy.h * k + GAPY);
  const idx = Math.max(0, wn.systems.findIndex((sy) => c.hongNo >= sy.from && c.hongNo <= sy.to));
  const { start, end } = pageOf(idx, hs, c.H - HEAD_H - botPad(c));
  let y = HEAD_H;
  for (let i = start; i < end; i += 1) {
    const sy = wn.systems[i];
    blit(c, {
      key: `west:${i}:${Math.round(k * 1000)}`, kind: 'west', sys: i,
      crop: { x: 0, y: 0, w: sy.w, h: sy.h },
      dst: { x: SIDE, y, w: sy.w * k, h: sy.h * k },
    });
    const br = sy.bars.get(c.hongNo);
    if (br) {
      c.ctx.fillStyle = BAR_INK;
      c.ctx.fillRect(SIDE + br.x * k, y + br.y * k, br.w * k, br.h * k);
    }
    y += sy.h * k + GAPY;
  }
  foot(c);
}

// ── สากล · ทีละบรรทัด (ซูม) ──────────────────────────────────────────
//  ★ ต่างจาก "เต็มหน้า" ตรงที่ **บรรทัดที่กำลังเล่นอยู่บนสุดเสมอ** แล้วไล่บรรทัด
//    ถัดไปลงมาจนเต็มจอ (เต็มหน้าแบ่งเป็นหน้าตายตัวแล้วกระโดดทีละหน้า)
//  ★ บรรทัดที่ยังไม่ถึงจางลง — สายตาเกาะบรรทัดที่กำลังเล่นได้โดยยังเห็นทางข้างหน้า
//  ★★ ทำไมตัวโน้ตไม่ได้ใหญ่กว่าแบบเต็มหน้า ★★ หนึ่งบรรทัดสากล = ภาพหนึ่งใบที่
//    เอนจินพ่นมาทั้งใบ ยังตัดเอาเฉพาะบางห้องไม่ได้ (ต่างจากกระดาษไทยที่ตัดได้)
//    → ถ้าจะซูมเข้าไปในบรรทัดจริง ๆ ต้องเพิ่มการตัดภาพให้ tile ฝั่งสากลก่อน
export function drawWesternZoom(c: FrameCtx) {
  bg(c); header(c);
  const wn = c.western;
  if (!wn || !wn.systems.length) return;
  const SIDE = side(c); const HEAD_H = headH(c);
  const GAPY = Math.round(30 * unit(c));
  const kw = (c.W - SIDE * 2) / wn.systems[0].w;
  const cur = Math.max(0, wn.systems.findIndex((sy) => c.hongNo >= sy.from && c.hongNo <= sy.to));
  const avail = c.H - HEAD_H - botPad(c);

  // ★★ ยอมหดนิดเดียวเพื่อให้ได้ "บรรทัดถัดไป" มาด้วย ★★ ที่ความกว้างเต็มจอ
  //   หนึ่งบรรทัดสากลสูงราวครึ่งจอแนวนอน — สองบรรทัดเกินไปนิดเดียว ปล่อยไว้
  //   จะเหลือครึ่งจอล่างเป็นที่ว่าง (เห็นจากคลิปจริง 2026-08-20)
  //   ★ หดได้ไม่เกิน ๒๒% ถ้าต้องหดกว่านั้นแปลว่าไม่คุ้ม — เอาบรรทัดเดียวแล้ว
  //     **จัดกึ่งกลางแนวตั้ง** แทน ดีกว่าลอยอยู่บนแล้วโล่งข้างล่าง
  let k = kw;
  const next = wn.systems[cur + 1];
  if (next) {
    const needTwo = wn.systems[cur].h + next.h;
    if (needTwo * kw + GAPY > avail) {
      const k2 = (avail - GAPY) / needTwo;
      if (k2 >= kw * 0.78) k = k2;
    }
  }

  // เก็บรายการแถวก่อน แล้วค่อยวาด — ต้องรู้ความสูงรวมเพื่อจัดกึ่งกลาง
  const rows: number[] = [];
  let used = 0;
  for (let i = cur; i < wn.systems.length; i += 1) {
    const h = wn.systems[i].h * k;
    if (rows.length && used + GAPY + h > avail) break;
    used += (rows.length ? GAPY : 0) + h;
    rows.push(i);
  }
  let y = HEAD_H + Math.round(Math.max(0, (avail - used) / 2));
  for (const i of rows) {
    const sy = wn.systems[i];
    const h = sy.h * k;
    if (i > cur) c.ctx.globalAlpha = DIM_ROW;
    blit(c, {
      key: `west:${i}:${Math.round(k * 1000)}`, kind: 'west', sys: i,
      crop: { x: 0, y: 0, w: sy.w, h: sy.h },
      dst: { x: SIDE, y, w: sy.w * k, h },
    });
    c.ctx.globalAlpha = 1;
    if (i === cur) {
      const br = sy.bars.get(c.hongNo);
      if (br) {
        c.ctx.fillStyle = BAR_INK;
        c.ctx.fillRect(SIDE + br.x * k, y + br.y * k, br.w * k, br.h * k);
      }
    }
    y += h + GAPY;
  }
  foot(c);
}

/** แถบล่างของเฟรม — มีแค่คำโปรยกับป้ายแบรนด์
 *  ★ ป้าย "บรรทัดที่ 1–5 จาก 54" / "ห้องที่ 14" **ถูกตัดออกแล้ว** (เจ้าของสั่ง 2026-08-20)
 *    เพราะกระดาษมีเลขห้องกำกับทุกห้องอยู่แล้ว — ป้ายซ้ำของที่มี แล้วกินที่ของโน้ต */
function foot(c: FrameCtx) {
  credit(c);
}

/** ── แถบเครดิตท้ายภาพ: คำโปรย + ป้ายแบรนด์ ARAN STUDIO ────────────────
 *  ★★ เจ้าของสั่งเอง (2026-08-20) ★★ ป้ายแบรนด์ต้องเป็น **รูปเดียวกันทุกโปรแกรม
 *    ของเรา** เหมือนโลโก้ — แคปซูลพื้นสีน้ำตาลอมเขียว ตัวอักษรขาวเว้นระยะห่าง
 *    (ต้นแบบ: ภาพที่เจ้าของส่งมา · สีพื้น #6A6558 วัดจากไฟล์นั้นตรง ๆ)
 *  ★ นี่คือข้อยกเว้นของกฎ "ห้ามใส่ชื่อโปรแกรมลงของที่ออกไป" ซึ่งยังใช้กับ
 *    **กระดาษพิมพ์** เหมือนเดิม — กระดาษเป็นของลูกค้า แต่คลิปเอาไปลงโซเชียล
 *  ★ วางเป็นแถวเดียว: คำโปรย · เว้นวรรค · ป้าย แล้วจัดทั้งกลุ่มให้กึ่งกลาง
 *    (วัดความกว้างจริงทั้งสองชิ้นก่อน ไม่พึ่ง textAlign — ดูเหตุผลที่ `header`)
 */
function credit(c: FrameCtx) {
  const u = unit(c);
  const fs = Math.round(19 * u);
  // ★ กล่องเตี้ยลงจาก 31 (เจ้าของทัก 2026-08-20: "box สูงไป บีบความสูงลงมาอีก")
  //   สัดส่วนกล่อง:ตัวอักษร ≈ 1.6 เท่า ใกล้ภาพต้นแบบมากกว่าเดิมที่ 2.1 เท่า
  const badgeH = Math.round(24 * u);
  const padX = Math.round(13 * u);
  const track = Math.max(1, Math.round(1.6 * u));      // ระยะห่างตัวอักษรของป้าย
  const gap = Math.round(14 * u);
  const cy = c.H - Math.round(30 * u);                 // กึ่งกลางแนวตั้งของแถบ

  c.ctx.font = `${fs}px 'IBM Plex Sans Thai', sans-serif`;
  const tw = c.ctx.measureText(CREDIT).width;

  const bf = `600 ${Math.round(15 * u)}px 'IBM Plex Sans Thai', sans-serif`;
  c.ctx.font = bf;
  const bw = trackedWidth(c.ctx, BRAND, track) + padX * 2;

  let x = Math.round((c.W - (tw + gap + bw)) / 2);
  c.ctx.font = `${fs}px 'IBM Plex Sans Thai', sans-serif`;
  c.ctx.fillStyle = CREDIT_INK;
  c.ctx.fillText(CREDIT, x, cy + Math.round(fs * 0.36));
  x += tw + gap;

  // ★ กล่องสี่เหลี่ยม **ลบมุมแค่นิดเดียว** ไม่ใช่แคปซูล (เจ้าของทัก 2026-08-20)
  //   วัดจากภาพต้นแบบ: กล่องสูง 18 px รัศมีราว 3 px = ราว 0.17 ของความสูง
  //  ★★ ต้องวาดด้วยมุมโค้งสี่มุมจริง ๆ ★★ สูตรเดิมใช้ครึ่งวงกลมสองข้าง ซึ่งถูกเฉพาะ
  //    ตอนเป็นแคปซูล (รัศมี = ครึ่งความสูง) · พอรัศมีเล็กลงกล่องออกมา **เบี้ยว**
  //    เหมือนสี่เหลี่ยมด้านขนาน (เห็นจากคลิปจริง ไม่ใช่จากโค้ด 2026-08-20)
  const by = Math.round(cy - badgeH / 2);
  const r = Math.max(2, Math.round(badgeH * 0.17));
  roundRect(c.ctx, x, by, bw, badgeH, r);
  c.ctx.fillStyle = BRAND_BG;
  c.ctx.fill();

  c.ctx.font = bf;
  c.ctx.fillStyle = BRAND_INK;
  drawTracked(c.ctx, BRAND, x + padX, cy + Math.round(5 * u), track);
}

/** สี่เหลี่ยมมุมมน — ใช้ `arcTo` ซึ่งมีมาแต่ไหนแต่ไร (ไม่พึ่ง `ctx.roundRect` ที่ยังใหม่) */
function roundRect(
  ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number,
) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y); ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r); ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h); ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r); ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

/** ★ วาดทีละตัวอักษรเอง — `ctx.letterSpacing` ไม่มีในเอนจินทุกรุ่นที่เรารองรับ
 *  และของที่ "ได้บ้างไม่ได้บ้าง" บนภาพที่อัดไปแล้วไม่มีใครฟ้อง */
function trackedWidth(ctx: CanvasRenderingContext2D, s: string, track: number) {
  let w = 0;
  for (const ch of s) w += ctx.measureText(ch).width + track;
  return w - track;
}

function drawTracked(ctx: CanvasRenderingContext2D, s: string, x: number, y: number, track: number) {
  let cx = x;
  for (const ch of s) {
    ctx.fillText(ch, cx, y);
    cx += ctx.measureText(ch).width + track;
  }
}

/** คำโปรยท้ายภาพ (เจ้าของกำหนดถ้อยคำเอง — ห้ามแก้) */
export const CREDIT = 'THAI SCORE : โปรแกรมเขียนโน้ตเพลงไทยพร้อมแปลงเป็นโน้ตสากล';
/** ★ ป้ายแบรนด์ของ ARAN STUDIO — ใช้รูปเดียวกันนี้กับทุกโปรแกรมของเรา */
export const BRAND = 'ARAN STUDIO';
const BRAND_BG = '#6a6558';
const BRAND_INK = '#faf8f4';
const CREDIT_INK = 'rgba(111,97,81,.72)';

/** ★ ตัวแรกคือ **ค่าตั้งต้น** (เจ้าของเคาะ 2026-08-19) — ที่เหลือให้ผู้ใช้เลือกได้ */
