/** ★★ ชิ้นภาพที่เฟรมนี้ต้องใช้ — เรียกก่อนวาดเสมอ ★★
 *  ★ ได้มาจากการ **ให้ตัววาดตัวจริงเดินหนึ่งรอบ** แล้วดักว่ามันขอชิ้นไหนบ้าง
 *    ไม่ใช่เขียนตรรกะคำนวณตำแหน่งซ้ำอีกชุด — สองชุดจะหลุดกันวันใดวันหนึ่ง
 *  ★ รอบเดินแผนวาดของทิ้งลงผ้าใบด้วย แต่ไม่เป็นไร: ตัววาดจริงเริ่มด้วยล้างผ้าใบเสมอ
 */
export function planFor(draw: (c: FrameCtx) => void, c: FrameCtx): Tile[] {
  COLLECT = [];
  try { draw(c); } finally { /* เก็บผลไว้ก่อนล้าง */ }
  const out = COLLECT;
  COLLECT = null;
  return out;
}

let COLLECT: Tile[] | null = null;
